#include <stdio.h>
#include <queue>
#include <ctype.h>
#include <vector>
#include <string.h>
using namespace std;

#define INF 12345678

struct Cell {
    int x;
    int y;
    int id;
};

struct Capacity {
    int ids[1000];
    int count;
    int active;
};

Capacity caps[100][100];
vector<int> adj[1000];
int n, limit;
int leftMatch[1000], rightMatch[1000], visited[1000];
char gridA[1000][1000], gridB[1000][1000];
int distA[1000][1000], distB[1000][1000];
queue<Cell> q;

void bfsFrom(Cell start);
void bfsTo(Cell start);
int maxMatching(int nodes);
bool findPath(int u);

int main() {
    int i, j, k, l;
    Cell temp, temp1;

    scanf("%d %d", &n, &limit);

    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            distA[i][j] = INF;
        }
    }

    for (i = 0; i < n; i++) {
        scanf("%s", gridA[i]);
    }

    for (i = 0; i < n; i++) {
        scanf("%s", gridB[i]);
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (gridA[i][j] == 'Z') {
                temp.x = i;
                temp.y = j;
                bfsFrom(temp);
            }
        }
    }

    int marker = 1;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(gridB[i][j])) {
                k = gridB[i][j] - '0';
                if (k > 0) caps[i][j].active = 1;
                caps[i][j].count = k;
                for (l = 1; l <= k; l++) {
                    caps[i][j].ids[l] = marker++;
                }
            }
        }
    }

    marker = 1;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(gridA[i][j])) {
                k = gridA[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    temp.x = i; temp.y = j; temp.id = marker++;
                    bfsTo(temp);
                }
            }
        }
    }

    printf("%d\n", maxMatching(marker - 1));
    return 0;
}

bool findPath(int u) {
    if (visited[u]) return false;
    visited[u] = 1;
    for (int i = 0; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if (leftMatch[v] == -1) {
            leftMatch[v] = u;
            rightMatch[u] = i;
            return true;
        } else if (findPath(leftMatch[v])) {
            leftMatch[v] = u;
            rightMatch[u] = i;
            return true;
        }
    }
    return false;
}

int maxMatching(int nodes) {
    memset(leftMatch, -1, sizeof(leftMatch));
    memset(rightMatch, -1, sizeof(rightMatch));
    int done;
    do {
        done = 1;
        memset(visited, 0, sizeof(visited));
        for (int i = 1; i <= nodes; i++) {
            if (rightMatch[i] == -1 && findPath(i)) done = 0;
        }
    } while (!done);
    int cnt = 0;
    for (int i = 1; i <= nodes; i++) {
        if (rightMatch[i] != -1) cnt++;
    }
    return cnt;
}

void bfsTo(Cell start) {
    int i, j, k, l;
    Cell temp, temp1;
    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            distB[i][j] = INF;
        }
    }
    i = start.x; j = start.y;
    distB[i][j] = 0;
    q.push(start);
    while (!q.empty()) {
        temp = q.front(); q.pop();
        i = temp.x; j = temp.y;
        if (distB[i][j] > limit) continue;
        if (gridA[i][j] == 'Y') continue;
        if (caps[i][j].active == 1) {
            if (distB[i][j] <= limit && distB[i][j] <= distA[i][j]) {
                for (k = 1; k <= caps[i][j].count; k++) {
                    adj[start.id].push_back(caps[i][j].ids[k]);
                }
            }
        }
        if (distB[i][j] >= distA[i][j]) continue;
        // up
        if (i - 1 >= 0) {
            if (distB[i - 1][j] > distB[i][j] + 1) {
                distB[i - 1][j] = distB[i][j] + 1;
                temp1.x = i - 1; temp1.y = j;
                q.push(temp1);
            }
        }
        // down
        if (i + 1 < n) {
            if (distB[i + 1][j] > distB[i][j] + 1) {
                distB[i + 1][j] = distB[i][j] + 1;
                temp1.x = i + 1; temp1.y = j;
                q.push(temp1);
            }
        }
        // left
        if (j - 1 >= 0) {
            if (distB[i][j - 1] > distB[i][j] + 1) {
                distB[i][j - 1] = distB[i][j] + 1;
                temp1.x = i; temp1.y = j - 1;
                q.push(temp1);
            }
        }
        // right
        if (j + 1 < n) {
            if (distB[i][j + 1] > distB[i][j] + 1) {
                distB[i][j + 1] = distB[i][j] + 1;
                temp1.x = i; temp1.y = j + 1;
                q.push(temp1);
            }
        }
    }
}

void bfsFrom(Cell start) {
    int i, j, k, l;
    Cell temp, temp1;
    i = start.x; j = start.y;
    distA[i][j] = 0;
    q.push(start);
    while (!q.empty()) {
        temp = q.front(); q.pop();
        i = temp.x; j = temp.y;
        if (gridA[i][j] == 'Y') continue;
        // up
        if (i - 1 >= 0) {
            if (distA[i - 1][j] > distA[i][j] + 1) {
                distA[i - 1][j] = distA[i][j] + 1;
                temp1.x = i - 1; temp1.y = j;
                q.push(temp1);
            }
        }
        // down
        if (i + 1 < n) {
            if (distA[i + 1][j] > distA[i][j] + 1) {
                distA[i + 1][j] = distA[i][j] + 1;
                temp1.x = i + 1; temp1.y = j;
                q.push(temp1);
            }
        }
        // left
        if (j - 1 >= 0) {
            if (distA[i][j - 1] > distA[i][j] + 1) {
                distA[i][j - 1] = distA[i][j] + 1;
                temp1.x = i; temp1.y = j - 1;
                q.push(temp1);
            }
        }
        // right
        if (j + 1 < n) {
            if (distA[i][j + 1] > distA[i][j] + 1) {
                distA[i][j + 1] = distA[i][j] + 1;
                temp1.x = i; temp1.y = j + 1;
                q.push(temp1);
            }
        }
    }
}
